{
  "info": {
    "description": "Raidiam Connect API",
    "license": {
      "name": "MIT",
      "url": "https://mit-license.org"
    },
    "contact": {
      "email": "support@raidiam.com"
    },
    "title": "Raidiam Connect",
    "version": "1.39.0"
  },
  "servers": [
    {
      "url": "https://matls-api.directory.openfinance.ae"
    },
    {
      "url": "https://matls-api.sandbox.directory.openfinance.ae"
    }
  ],
  "source_path": "/organisations/{OrganisationId}/contacts",
  "operations": {
    "parameters": [
      {
        "$ref": "#/components/parameters/OrganisationId"
      },
      {
        "$ref": "#/components/parameters/x-fapi-auth-date"
      },
      {
        "$ref": "#/components/parameters/x-fapi-customer-ip-address"
      },
      {
        "$ref": "#/components/parameters/x-fapi-interaction-id"
      },
      {
        "$ref": "#/components/parameters/x-customer-user-agent"
      }
    ],
    "get": {
      "summary": "Get the contacts for the given organisation",
      "description": "get all contacts for an organisations",
      "operationId": "getOrganisationContacts",
      "parameters": [
        {
          "$ref": "#/components/parameters/PageNumber"
        },
        {
          "$ref": "#/components/parameters/PageSize"
        },
        {
          "$ref": "#/components/parameters/PageSort"
        }
      ],
      "tags": [
        "Organisations",
        "Contacts",
        "Public",
        "Closed"
      ],
      "responses": {
        "200": {
          "$ref": "#/components/responses/ContactsPage"
        },
        "400": {
          "$ref": "#/components/responses/BadRequest"
        },
        "401": {
          "$ref": "#/components/responses/Unauthorized"
        },
        "403": {
          "$ref": "#/components/responses/Forbidden"
        },
        "404": {
          "$ref": "#/components/responses/NotFound"
        },
        "406": {
          "$ref": "#/components/responses/NotAcceptable"
        },
        "429": {
          "$ref": "#/components/responses/TooManyRequests"
        },
        "500": {
          "$ref": "#/components/responses/InternalServerError"
        },
        "502": {
          "$ref": "#/components/responses/BadGateway"
        },
        "504": {
          "$ref": "#/components/responses/UpstreamTimeout"
        }
      },
      "security": [
        {
          "authorizer": []
        },
        {
          "oAuth": [
            "directory:website",
            "directory:software"
          ]
        }
      ],
      "x-amazon-apigateway-integration": {
        "uri": "${organisation_read_arn}",
        "passthroughBehavior": "when_no_match",
        "httpMethod": "POST",
        "timeoutInMillis": 15000,
        "type": "aws_proxy"
      }
    },
    "post": {
      "summary": "Post a contact for the given organisation",
      "description": "creates a contact for an organisation",
      "operationId": "createOrganisationContact",
      "tags": [
        "Organisations",
        "Contacts",
        "Public",
        "Closed"
      ],
      "requestBody": {
        "$ref": "#/components/requestBodies/ContactRequest"
      },
      "responses": {
        "201": {
          "$ref": "#/components/responses/Contact"
        },
        "400": {
          "$ref": "#/components/responses/BadRequest"
        },
        "401": {
          "$ref": "#/components/responses/Unauthorized"
        },
        "403": {
          "$ref": "#/components/responses/Forbidden"
        },
        "406": {
          "$ref": "#/components/responses/NotAcceptable"
        },
        "409": {
          "$ref": "#/components/responses/Conflict"
        },
        "429": {
          "$ref": "#/components/responses/TooManyRequests"
        },
        "500": {
          "$ref": "#/components/responses/InternalServerError"
        },
        "502": {
          "$ref": "#/components/responses/BadGateway"
        },
        "504": {
          "$ref": "#/components/responses/UpstreamTimeout"
        }
      },
      "security": [
        {
          "authorizer": []
        },
        {
          "oAuth": [
            "directory:website"
          ]
        }
      ],
      "x-amazon-apigateway-integration": {
        "uri": "${organisation_write_arn}",
        "passthroughBehavior": "when_no_match",
        "httpMethod": "POST",
        "timeoutInMillis": 29000,
        "type": "aws_proxy"
      }
    }
  }
}

{
  "in": "header",
  "name": "x-fapi-auth-date",
  "required": false,
  "description": "The time when the PSU last logged in with the TPP. \nAll dates in the HTTP headers are represented as RFC 7231 Full Dates. An example is below: \nSun, 10 Sep 2017 19:43:31 UTC",
  "schema": {
    "type": "string",
    "pattern": "^(Mon|Tue|Wed|Thu|Fri|Sat|Sun), \\d{2} (Jan|Feb|Mar|Apr|May|Jun|Jul|Aug|Sep|Oct|Nov|Dec) \\d{4} \\d{2}:\\d{2}:\\d{2} (GMT|UTC)$"
  }
}

{
  "in": "header",
  "name": "x-fapi-customer-ip-address",
  "required": false,
  "description": "The PSU's IP address if the PSU is currently logged in with the TPP.",
  "schema": {
    "type": "string"
  }
}

{
  "in": "header",
  "name": "x-fapi-interaction-id",
  "required": false,
  "description": "An RFC4122 UID used as a correlation id.",
  "schema": {
    "type": "string"
  }
}

{
  "in": "header",
  "name": "x-customer-user-agent",
  "description": "Indicates the user-agent that the PSU is using.",
  "required": false,
  "schema": {
    "type": "string"
  }
}

{
  "in": "query",
  "name": "page",
  "schema": {
    "type": "integer"
  },
  "description": "The page number to return of the result set"
}

{
  "in": "query",
  "name": "size",
  "schema": {
    "type": "integer"
  },
  "description": "The size of the pages to return"
}

{
  "type": "object",
  "properties": {
    "number": {
      "type": "integer",
      "description": "Page number"
    },
    "sort": {
      "$ref": "#/components/schemas/PageableSort"
    },
    "size": {
      "type": "integer",
      "description": "Size of the page"
    },
    "offset": {
      "type": "integer",
      "description": "Offset"
    },
    "sorted": {
      "type": "boolean",
      "description": "Is the page sorted"
    },
    "unpaged": {
      "type": "boolean",
      "description": "Is this an unpaged response"
    },
    "mode": {
      "type": "string",
      "description": "Pageable mode. Possible values are OFFSET, CURSOR_NEXT, CURSOR_PREVIOUS"
    }
  }
}

{
  "type": "object",
  "properties": {
    "sorted": {
      "type": "boolean"
    },
    "orderBy": {
      "type": "array",
      "items": {
        "type": "object",
        "properties": {
          "property": {
            "type": "string",
            "description": "Name of the property used for sorting",
            "example": "createdAt"
          },
          "direction": {
            "type": "string",
            "description": "Direction of sort, i.e. ascending or descending",
            "enum": [
              "ASC",
              "DESC"
            ]
          },
          "ignoreCase": {
            "type": "boolean",
            "description": "Was the case ignored"
          },
          "ascending": {
            "type": "boolean",
            "description": "Whether ascending"
          }
        }
      }
    }
  }
}

{
  "type": "object",
  "properties": {
    "ContactId": {
      "type": "string",
      "pattern": "^[^<>]*$",
      "description": "Unique contact ID for the row."
    },
    "OrganisationId": {
      "$ref": "#/components/schemas/OrganisationId"
    },
    "ContactType": {
      "$ref": "#/components/schemas/ContactType"
    },
    "FirstName": {
      "type": "string",
      "pattern": "^[^<>]*$",
      "maxLength": 255
    },
    "LastName": {
      "type": "string",
      "pattern": "^[^<>]*$",
      "maxLength": 255
    },
    "Department": {
      "type": "string",
      "pattern": "^[^<>]*$",
      "maxLength": 255
    },
    "EmailAddress": {
      "type": "string",
      "pattern": "^(([^<>()\\[\\]\\\\.,;:\\s@\"]+(\\.[^<>()\\[\\]\\\\.,;:\\s@\"]+)*)|(\".+\"))@((\\[[0-9]{1,3}\\.[0-9]{1,3}\\.[0-9]{1,3}\\.[0-9]{1,3}\\])|(([a-zA-Z\\-0-9]+\\.)+[a-zA-Z]{2,}))$",
      "x-pattern-message": "EmailAddress must be a valid email",
      "maxLength": 255
    },
    "PhoneNumber": {
      "type": "string",
      "pattern": "^[^<>]*$",
      "maxLength": 18
    },
    "AddressLine1": {
      "type": "string",
      "pattern": "^[^<>]*$",
      "description": "Address line 1",
      "maxLength": 255
    },
    "AddressLine2": {
      "type": "string",
      "pattern": "^[^<>]*$",
      "description": "Address line 2",
      "maxLength": 255
    },
    "City": {
      "type": "string",
      "pattern": "^[^<>]*$",
      "description": "City",
      "maxLength": 255
    },
    "Postcode": {
      "type": "string",
      "pattern": "^[^<>]*$",
      "description": "Postcode",
      "maxLength": 40
    },
    "Country": {
      "type": "string",
      "pattern": "^[^<>]*$",
      "description": "Country",
      "maxLength": 255
    },
    "AdditionalInformation": {
      "type": "string",
      "pattern": "^[^<>]*$",
      "description": "Any additional user information",
      "maxLength": 65535
    },
    "PgpPublicKey": {
      "type": "string",
      "pattern": "^[^<>]*$",
      "description": "A PGP Public Key in text form",
      "maxLength": 65535
    }
  }
}

{
  "description": "Too many requests, maximum capacity reached. Requests are now throttled.",
  "headers": {
    "x-fapi-interaction-id": {
      "schema": {
        "$ref": "#/components/schemas/xFapiInteractionId"
      }
    }
  }
}

{
  "description": "Upstream timeout, insufficient capacity to serve request. More capacity being brought online. Please try again.",
  "headers": {
    "x-fapi-interaction-id": {
      "schema": {
        "$ref": "#/components/schemas/xFapiInteractionId"
      }
    }
  }
}

{
  "type": "object",
  "properties": {
    "ContactType": {
      "$ref": "#/components/schemas/ContactType"
    },
    "FirstName": {
      "type": "string",
      "pattern": "^[^<>]*$",
      "maxLength": 255
    },
    "LastName": {
      "type": "string",
      "pattern": "^[^<>]*$",
      "maxLength": 255
    },
    "Department": {
      "type": "string",
      "pattern": "^[^<>]*$",
      "maxLength": 255
    },
    "EmailAddress": {
      "type": "string",
      "pattern": "^(([^<>()\\[\\]\\\\.,;:\\s@\"]+(\\.[^<>()\\[\\]\\\\.,;:\\s@\"]+)*)|(\".+\"))@((\\[[0-9]{1,3}\\.[0-9]{1,3}\\.[0-9]{1,3}\\.[0-9]{1,3}\\])|(([a-zA-Z\\-0-9]+\\.)+[a-zA-Z]{2,}))$",
      "x-pattern-message": "EmailAddress must be a valid email",
      "maxLength": 255
    },
    "PhoneNumber": {
      "type": "string",
      "pattern": "^[^<>]*$",
      "minLength": 1,
      "maxLength": 18
    },
    "AddressLine1": {
      "type": "string",
      "pattern": "^[^<>]*$",
      "description": "Address line 1",
      "maxLength": 255
    },
    "AddressLine2": {
      "type": "string",
      "pattern": "^[^<>]*$",
      "description": "Address line 2",
      "maxLength": 255
    },
    "City": {
      "type": "string",
      "pattern": "^[^<>]*$",
      "description": "City",
      "maxLength": 255
    },
    "Postcode": {
      "type": "string",
      "pattern": "^[^<>]*$",
      "description": "Postcode",
      "maxLength": 40
    },
    "Country": {
      "type": "string",
      "pattern": "^[^<>]*$",
      "description": "Country",
      "maxLength": 255
    },
    "AdditionalInformation": {
      "type": "string",
      "pattern": "^[^<>]*$",
      "description": "Any additional user information",
      "maxLength": 65535
    },
    "PgpPublicKey": {
      "type": "string",
      "pattern": "^[^<>]*$",
      "description": "A PGP Public Key in text form",
      "maxLength": 65535
    }
  },
  "required": [
    "ContactType",
    "EmailAddress",
    "PhoneNumber"
  ]
}
